var t=150;var a=[{id:`cooking-150-01`,theoryId:150,type:`single_choice`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Which live shellfish should you reject before cooking?`,ua:`Яких живих двостулкових молюсків слід відхилити перед приготуванням?`},explanation:{en:`FDA advises discarding broken-shell bivalves and live specimens that fail the tap test.`,ua:`FDA радить відмовлятися від молюсків із тріснутою мушлею та тих, що не реагують на постукування.`},options:[{id:`a`,text:{en:`Those with cracked shells or that fail to close when tapped`,ua:`Із тріснутою мушлею чи ті, що не закриваються після постукування`}},{id:`b`,text:{en:`Those with intact closed shells from approved sources`,ua:`Із цілою закритою мушлею від перевірених постачальників`}},{id:`c`,text:{en:`Those kept properly chilled`,ua:`Належно охолоджених`}}],answer:{optionIds:[`a`]}},{id:`cooking-150-02`,theoryId:150,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Eating raw oysters carries infection risks even when they come from a reputable seller.`,ua:`Вживання сирих устриць пов’язане з ризиком інфекцій навіть від надійного продавця.`},explanation:{en:`Raw shellfish may contain pathogenic organisms such as Vibrio; reputable sourcing does not remove all risk.`,ua:`Сирі молюски можуть містити збудники, зокрема Vibrio; надійне походження не усуває всіх ризиків.`},answer:{value:!0}},{id:`cooking-150-03`,theoryId:150,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match bivalve observations to decisions.`,ua:`Поєднайте ознаки двостулкових молюсків із рішеннями.`},explanation:{en:`Shell condition and reaction help assess live bivalves before cooking.`,ua:`Стан мушлі та реакція допомагають оцінювати живих молюсків до приготування.`},leftItems:[{id:`l1`,text:{en:`Broken shell before cooking`,ua:`Тріснута мушля до приготування`}},{id:`l2`,text:{en:`Open live clam that stays open when tapped`,ua:`Живий молюск не закривається після постукування`}},{id:`l3`,text:{en:`Closed or openable approved live shellfish`,ua:`Належний живий молюск від перевіреного постачальника`}}],rightItems:[{id:`r3`,text:{en:`Cook properly`,ua:`Належно приготувати`}},{id:`r2`,text:{en:`Reject as potentially dead`,ua:`Відмовитися як від потенційно мертвого`}},{id:`r1`,text:{en:`Discard`,ua:`Викинути`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-150-04`,theoryId:150,type:`sequence`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Order a basic safety workflow for live mussels.`,ua:`Упорядкуйте безпечне приготування живих мідій.`},explanation:{en:`FDA advises inspecting shellfish and discarding those that do not open during cooking.`,ua:`FDA радить оглядати молюсків та викидати ті, що не відкрилися під час приготування.`},steps:[{id:`s2`,text:{en:`Inspect shells and discard broken or nonresponsive specimens`,ua:`Перевірити мушлі й викинути пошкоджені або без реакції`}},{id:`s1`,text:{en:`Buy from an approved supplier and keep properly chilled`,ua:`Придбати в перевіреного постачальника та належно охолодити`}},{id:`s3`,text:{en:`Cook thoroughly and discard shells that do not open`,ua:`Ретельно приготувати та викинути мушлі, що не відкрилися`}}],answer:{order:[`s1`,`s2`,`s3`]}},{id:`cooking-150-05`,theoryId:150,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`After steaming mussels, several shells remain closed. What is the recommended action under FDA guidance?`,ua:`Після приготування мідій на парі кілька мушель залишилися закритими. Що рекомендує FDA?`},explanation:{en:`FDA recommends discarding bivalves that do not open during cooking.`,ua:`FDA рекомендує викидати двостулкових молюсків, що не відкрилися під час приготування.`},options:[{id:`a`,text:{en:`Discard unopened mussels`,ua:`Викинути мідії, які не відкрилися`}},{id:`b`,text:{en:`Pry them open and serve raw`,ua:`Розкрити силою та подати сирими`}},{id:`c`,text:{en:`Hide them in sauce`,ua:`Сховати їх у соусі`}}],answer:{optionIds:[`a`]}},{id:`cooking-150-06`,theoryId:150,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which shellfish statement is unsafe?`,ua:`Яке твердження про безпечність молюсків небезпечне?`},explanation:{en:`Lemon juice does not reliably eliminate pathogens in raw oysters.`,ua:`Лимонний сік не знищує надійно патогени в сирих устрицях.`},options:[{id:`a`,text:{en:`Source traceability matters`,ua:`Походження та простежуваність важливі`}},{id:`b`,text:{en:`Keep live shellfish properly cold`,ua:`Зберігати живих молюсків належно охолодженими`}},{id:`c`,text:{en:`Raw oysters are guaranteed safe if squeezed with lemon`,ua:`Сирі устриці гарантовано безпечні після додавання лимона`}}],answer:{optionIds:[`c`]}},{id:`cooking-150-07`,theoryId:150,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which precautions are appropriate for live bivalves?`,ua:`Які запобіжні заходи доречні для живих двостулкових молюсків?`},explanation:{en:`Shell inspection, traceable sourcing and thorough cooking reduce risk.`,ua:`Перевірка мушель, простежуване походження та повне приготування зменшують ризики.`},options:[{id:`a`,text:{en:`Buy from an approved, traceable supplier`,ua:`Купувати у перевіреного постачальника з простежуваним походженням`}},{id:`b`,text:{en:`Reject broken shells`,ua:`Відмовлятися від тріснутих мушель`}},{id:`c`,text:{en:`Discard mussels that remain closed after cooking`,ua:`Викидати мідії, що залишилися закритими після приготування`}},{id:`d`,text:{en:`Assume lemon juice makes raw shellfish pathogen-free`,ua:`Вважати, що лимонний сік усуває патогени в сирих молюсках`}}],answer:{optionIds:[`a`,`b`,`c`]}}];var n={theoryId:150,exercises:a};export{n as default,a as exercises,t as theoryId};